module uart_tx (
    input  wire       clk,
    input  wire       rst,
    input  wire [7:0] tx_data,
    input  wire       tx_start,
    output reg        tx_serial,
    output reg        tx_busy
);

    localparam S_IDLE  = 2'b00;
    localparam S_START = 2'b01;
    localparam S_DATA  = 2'b10;
    localparam S_STOP  = 2'b11;

    reg [1:0] state;
    reg [2:0] bit_idx;
    reg [7:0] data_buf;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state        <= S_IDLE;
            tx_serial <= 1'b1;
            tx_busy   <= 1'b0;
            bit_idx      <= 3'd0;
            data_buf     <= 8'd0;
        end else begin
            case (state)
                S_IDLE: begin
                    tx_serial <= 1'b1;
                    tx_busy   <= 1'b0;
                    if (tx_start) begin
                        data_buf    <= tx_data;
                        state       <= S_START;
                        tx_busy   <= 1'b1;
                    end
                end
                S_START: begin
                    tx_serial <= 1'b0; // Start bit
                    tx_busy   <= 1'b1;
                    bit_idx      <= 3'd0;
                    state        <= S_DATA;
                end
                S_DATA: begin
                    tx_serial <= data_buf[bit_idx];
                    tx_busy   <= 1'b1;
                    if (bit_idx == 3'd7) begin
                        state <= S_STOP;
                    end else begin
                        bit_idx <= bit_idx + 1'b1;
                    end
                end
                S_STOP: begin
                    tx_serial <= 1'b1; // Stop bit
                    tx_busy   <= 1'b1;
                    state        <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

endmodule
